messageHandlers.script:
if payload.get('tagPath') == self.view.params.tagPath:
	shared.Alerts.revertPending(self.getChild('Chk'), 'props.selected', payload.get('oldValue'))
	self.view.custom.timeOut.actionComplete = True

if not self.view.params.tagPath or payload.get('tagPath') != self.view.params.tagPath:
	return
if not payload.get('alreadyWritten'):
	try:
		shared.Audit.writeTag(
			payload['tagPath'],
			payload.get('value'),
			label=payload.get('label'),
			viewName=payload.get('viewName') or self.view.id.split('@')[0],
		)
	except:
		shared.ValveCommands.writeTag(payload.get('tagPath'), payload.get('value'))
self.view.custom.timeOut.actionComplete = True
